
const data=window.MATCHA_DATA, PAGE_SIZE=40;let page=1,activeQuery='',filtered=[],matchedSearchItems=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').toLowerCase().replace(/[_:/-]+/g,' ').replace(/\s+/g,' ').trim();
let spoilerMode=data.spoilers.defaultMode,spoilerStage=data.spoilers.defaultStage;
try{spoilerMode=localStorage.getItem('matcha-spoiler-mode')||spoilerMode;spoilerStage=Number(localStorage.getItem('matcha-spoiler-stage'))||spoilerStage}catch{}
const spoilerLimit=()=>spoilerMode==='complete'?Infinity:spoilerMode==='minimal'?1:spoilerStage;
function spoilerAllowed(type,id){if(spoilerMode==='complete')return true;if((data.spoilers.hidden[type]||[]).includes(id))return false;return (data.spoilers.stages[type]?.[id]||1)<=spoilerLimit()}
function spoilerGate(type,id){const stage=data.spoilers.stages[type]?.[id];return `<div class="spoiler-gate"><b>Hidden by ${esc(spoilerMode)} spoiler mode</b>${stage?`This content unlocks at progression stage ${stage}.`:data.spoilers.policy}</div>`}
const spoilerModeControl=document.getElementById('spoiler-mode'),spoilerStageControl=document.getElementById('spoiler-stage');spoilerModeControl.value=spoilerMode;
function renderStageOptions(){spoilerStageControl.innerHTML=data.progression.map((stage,index)=>{const number=index+1,title=spoilerMode==='complete'||number<=spoilerStage?`${number}. ${stage.title}`:`Stage ${number}`;return `<option value="${number}">${esc(title)}</option>`}).join('');spoilerStageControl.value=spoilerStage}
