spoilerModeControl.onchange=()=>{spoilerMode=spoilerModeControl.value;if(spoilerMode!=='progression'){spoilerStage=1;try{localStorage.setItem('matcha-spoiler-stage',spoilerStage)}catch{}}try{localStorage.setItem('matcha-spoiler-mode',spoilerMode)}catch{}updateSpoilerControls();refreshSpoilers()};spoilerStageControl.onchange=()=>{spoilerStage=Number(spoilerStageControl.value);try{localStorage.setItem('matcha-spoiler-stage',spoilerStage)}catch{}updateSpoilerControls();refreshSpoilers()};updateSpoilerControls();
const itemMatch=(x,q=activeQuery)=>q&&(norm(x.id).includes(q)||norm(x.name).includes(q));
function showPage(id,updateHash=true){document.querySelectorAll('.page').forEach(x=>{const active=x.id===id;x.classList.toggle('active',active);x.hidden=!active});document.querySelectorAll('.side button').forEach(x=>{const active=x.dataset.page===id;x.classList.toggle('active',active);x.ariaCurrent=active?'page':null});if(updateHash&&location.hash!==`#${id}`)location.hash=id;scrollTo(0,0);if(updateHash)document.getElementById('main-content').focus()}
