function slot(i,count=1){if(!i)return '<span class="slot"></span>';const visual=i.icon?`<img loading="lazy" src="${esc(i.icon)}" alt="${esc(i.name)}">`:`<span class="slot-fallback">${esc(i.name)}</span>`;return `<span class="slot" title="${esc(i.name)} (${esc(i.id)})">${visual}${count>1?`<span class="slot-count">${count}</span>`:''}</span>`}
function diagram(r){let input;if(r.type==='crafting_shaped'){const map={};r.ingredients.forEach(i=>map[i.symbol]=i);const rows=r.pattern.map(x=>x.padEnd(3,' '));while(rows.length<3)rows.push('   ');input=`<div class="craft-grid">${rows.flatMap(x=>[...x]).map(x=>slot(map[x])).join('')}</div>`}else if(r.type==='crafting_shapeless'){const items=[...r.ingredients];while(items.length<9)items.push(null);input=`<div class="craft-grid">${items.slice(0,9).map(i=>slot(i,i?.count)).join('')}</div>`}else input=`<div class="ingredients">${r.ingredients.map(i=>slot(i,i.count)).join('')}</div>`;return `<div class="visual-label">${esc(r.patternLabel)}</div><div class="recipe-visual">${input}<span class="arrow">➜</span>${slot({id:r.resultId,name:r.resultName,icon:r.icon},r.count)}</div>`}
function ingredient(i){return `<button class="ingredient ${itemMatch(i)?'matched':''}" data-lookup="${esc(i.id)}">${esc(i.name)}${i.count>1?' x'+i.count:''}</button>`}
function effectBadge(effect){const chance=effect.probability<1?` ${Math.round(effect.probability*100)}%`:'';return `<span class="effect ${esc(effect.category)}">${esc(effect.name)} ${effect.level} ${esc(effect.duration)}${chance}</span>`}
function foodBadges(food){if(!food)return '';const effects=food.effects.map(effectBadge);if(food.clearAll)effects.push('<span class="effect cleansing">Clears all effects</span>');if(food.removes.length)effects.push(`<span class="effect cleansing">Removes ${food.removes.length} harmful effects</span>`);return effects.length?`<div class="effect-badges">${effects.join('')}</div>`:''}
function foodDetails(food){if(!food)return '';const facts=[['Nutrition',food.nutrition??'Not specified'],['Saturation',food.saturation??'Not specified'],['Always edible',food.alwaysEdible?'Yes':'No'],['Consume time',food.consumeSeconds!=null?food.consumeSeconds+'s':'Default'],['Animation',food.animation||'Default'],['Remainder',food.remainder||'None']];const effects=food.effects.length?`<table class="effect-table"><tr><th>Effect</th><th>Level</th><th>Duration</th><th>Chance</th><th>Type</th></tr>${food.effects.map(e=>`<tr><td>${esc(e.name)}</td><td>${e.level}</td><td>${esc(e.duration)}</td><td>${Math.round(e.probability*100)}%</td><td><span class="effect ${esc(e.category)}">${esc(e.category)}</span></td></tr>`).join('')}</table>`:'<p>No status effects are applied.</p>';const cleansing=food.clearAll?'<p><span class="effect cleansing">Clears all active status effects</span></p>':food.removes.length?`<p><span class="effect cleansing">Removes:</span> ${food.removes.map(e=>esc(e.name)).join(', ')}</p>`:'';return `<section class="food-details"><h2>Food properties</h2><div class="food-facts">${facts.map(([k,v])=>`<div class="food-fact"><b>${esc(k)}</b>${esc(v)}</div>`).join('')}</div><h3>Effects when consumed</h3>${effects}${cleansing}</section>`}
function card(r){const resultMatch=itemMatch({id:r.resultId,name:r.resultName})?' matched':'',food=r.foodKey?foodByKey.get(r.foodKey):null;return `<article class="recipe"><img class="icon" loading="lazy" src="${esc(r.icon)}" alt=""><div class="result${resultMatch}"><b>${esc(r.resultName)}</b>${r.count>1?' x'+r.count:''} ${r.custom?'<span class="custom">custom item</span>':''}<div class="id">${esc(r.resultId)}</div>${foodBadges(food)}</div><div class="ingredients">${r.ingredients.map(ingredient).join('')}</div><div class="type">${esc(r.patternLabel)}<br><small>click for diagram and effects</small></div><div class="detail">${diagram(r)}${foodDetails(food)}<p><b>Recipe ID:</b> <code>${esc(r.id)}</code><br><b>Recipe type:</b> <code>${esc(r.type)}</code></p></div></article>`}
function wire(root){root.querySelectorAll('.recipe').forEach(x=>x.onclick=e=>{if(!e.target.closest('.ingredient'))x.classList.toggle('open')});root.querySelectorAll('.ingredient').forEach(x=>x.onclick=()=>{showPage('reverse');document.getElementById('reverse-search').value=x.dataset.lookup;reverse()})}
function searchItemHTML(item){const icon=item.icon||iconMap.get(item.id),key=item.key||item.id,id=item.underlyingId||item.id,food=item.foodKey?foodByKey.get(item.foodKey):null;return `<button class="search-item-card" data-obtain-id="${esc(key)}">${icon?`<img src="${esc(icon)}" alt="">`:''}<span><b>${esc(item.name)}</b><code>${esc(id)}</code>${foodBadges(food)}<small>View item information</small></span></button>`}
