function renderPage(){const start=(page-1)*PAGE_SIZE,end=start+PAGE_SIZE,root=document.getElementById('all-results');const items=matchedSearchItems.length?`<section class="matching-items"><h2>Matching items <span class="count">${matchedSearchItems.length}</span></h2>${matchedSearchItems.slice(0,20).map(searchItemHTML).join('')}</section>`:'';const recipes=filtered.slice(start,end).map(card).join('')||'<div class="empty">No matching recipes.</div>';root.innerHTML=items+recipes;wireSearchItems(root);wire(root);const pages=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));document.getElementById('pager').innerHTML=`<button id="prev" ${page===1?'disabled':''}>Previous</button><span>Page ${page} of ${pages}</span><button id="next" ${page===pages?'disabled':''}>Next</button>`;document.getElementById('prev').onclick=()=>{page--;renderPage();scrollTo(0,0)};document.getElementById('next').onclick=()=>{page++;renderPage();scrollTo(0,0)}}
function search(){activeQuery=norm(document.getElementById('all-search').value);const category=document.getElementById('category').value;let pool=data.recipes.filter(r=>spoilerAllowed('recipe',r.id)&&(!category||r.namespace===category));if(activeQuery){matchedSearchItems=data.items.filter(item=>spoilerAllowed('item',item.key)&&(norm(item.id).includes(activeQuery)||norm(item.name).includes(activeQuery)||item.lore.some(line=>norm(line).includes(activeQuery))||item.properties.some(value=>norm(value).includes(activeQuery)))).sort((a,b)=>(norm(a.id)===activeQuery||norm(a.name)===activeQuery?-1:0)-(norm(b.id)===activeQuery||norm(b.name)===activeQuery?-1:0));const creates=pool.filter(r=>itemMatch({id:r.resultId,name:r.resultName}));const uses=pool.filter(r=>r.ingredients.some(i=>itemMatch(i))&&!creates.includes(r));const related=pool.filter(r=>norm(r.search).includes(activeQuery)&&!creates.includes(r)&&!uses.includes(r));filtered=[...creates,...uses,...related];document.getElementById('all-stats').textContent=`${matchedSearchItems.length} matching items; ${creates.length} recipes create them; ${uses.length} recipes use them; ${related.length} other matches.`}else{matchedSearchItems=[];filtered=pool;document.getElementById('all-stats').textContent=`${filtered.length.toLocaleString()} visible recipes. Only ${PAGE_SIZE} render at a time.`}page=1;renderPage()}
