document.getElementById('reverse-go').onclick=reverse;document.getElementById('reverse-search').onkeydown=e=>{if(e.key==='Enter')reverse()};
const itemMap=new Map();
const canonical=id=>String(id).includes(':')?String(id):'minecraft:'+id;
const iconMap=new Map();data.recipes.forEach(r=>{if(r.icon)iconMap.set(canonical(r.resultId),r.icon);r.ingredients.forEach(i=>{if(i.icon)iconMap.set(canonical(i.id),i.icon)})});
