 const loot=item.sources.length?`<h2>Loot and world sources</h2><div class="source-list">${item.sources.map(source=>`<div class="source"><b>${esc(source.kind)}</b>${esc(source.location)}<br><code>${esc(source.id)}</code></div>`).join('')}</div>`:'';
 const trades=item.trades.length?`<h2>Villager trades</h2><div class="source-list">${item.trades.map(trade=>`<div class="source"><b>${esc(trade.profession)} (${esc(trade.level)})</b>Cost: ${esc(trade.cost)}${trade.container?`<br>Contained in: ${esc(trade.container)}`:''}<br><code>${esc(trade.id)}</code></div>`).join('')}</div>`:'';
 const none=!item.recipes.length&&!item.sources.length&&!item.trades.length?'<div class="empty">No pack-defined acquisition source was found. This item may retain its normal vanilla source.</div>':'';
