document.getElementById('obtain-go').onclick=obtain;document.getElementById('obtain-search').onkeydown=e=>{if(e.key==='Enter')obtain()};
let tradePage=1,tradeFiltered=data.trades;const TRADE_PAGE_SIZE=40;
function tradeItem(item){const icon=item.icon||iconMap.get(item.id),count=item.count===1?'':`${esc(item.count)} `;return `<span class="trade-item">${icon?`<img loading="lazy" src="${esc(icon)}" alt="">`:''}<span><b>${count}${esc(item.name)}</b><code>${esc(item.id)}</code></span></span>`}
function tradeCard(trade){const contents=trade.bundleContents.length?`<details class="trade-contents"><summary>Bundle contents (${trade.bundleContents.length})</summary><div class="trade-items">${trade.bundleContents.map(tradeItem).join('')}</div></details>`:'';const facts=[['Maximum uses',trade.maxUses??'Not specified'],['Villager XP',trade.xp??'Not specified'],['Reputation discount',trade.reputationDiscount??'Not specified']];return `<article class="trade-card"><div class="trade-heading"><div><strong>${esc(trade.profession)}</strong><span>${esc(trade.level)}</span></div><code>${esc(trade.id)}</code></div><div class="trade-exchange"><div class="trade-items">${trade.costs.map(tradeItem).join('')||'<span>Pack-defined cost</span>'}</div><span class="trade-arrow">➜</span>${tradeItem(trade.result)}</div>${contents}<div class="trade-facts">${facts.map(([key,value])=>`<div><b>${esc(key)}</b>${esc(value)}</div>`).join('')}</div><p class="provenance">${esc(trade.source)}</p></article>`}
function renderTrades(){const start=(tradePage-1)*TRADE_PAGE_SIZE,pages=Math.max(1,Math.ceil(tradeFiltered.length/TRADE_PAGE_SIZE));document.getElementById('trade-results').innerHTML=tradeFiltered.slice(start,start+TRADE_PAGE_SIZE).map(tradeCard).join('')||'<div class="empty">No trades match these filters.</div>';document.getElementById('trade-stats').textContent=`Showing ${tradeFiltered.length} of ${data.trades.length} pack-defined trades`;document.getElementById('trade-pager').innerHTML=`<button id="trade-prev" ${tradePage===1?'disabled':''}>Previous</button><span>Page ${tradePage} of ${pages}</span><button id="trade-next" ${tradePage===pages?'disabled':''}>Next</button>`;document.getElementById('trade-prev').onclick=()=>{tradePage--;renderTrades();scrollTo(0,0)};document.getElementById('trade-next').onclick=()=>{tradePage++;renderTrades();scrollTo(0,0)}}
function filterTrades(){const q=norm(document.getElementById('trade-search').value),profession=document.getElementById('trade-profession').value,level=document.getElementById('trade-level').value;tradeFiltered=data.trades.filter(trade=>spoilerAllowed('trade',trade.id)&&(!profession||trade.profession===profession)&&(!level||trade.level===level)&&(!q||[trade.id,trade.profession,trade.level,trade.result.id,trade.result.name,...trade.costs.flatMap(item=>[item.id,item.name]),...trade.bundleContents.flatMap(item=>[item.id,item.name])].some(value=>norm(value).includes(q))));tradePage=1;renderTrades()}
const tradeProfessions=[...new Set(data.trades.map(trade=>trade.profession))].sort(),tradeLevels=['Novice','Apprentice','Journeyman','Expert','Master','Any'].filter(level=>data.trades.some(trade=>trade.level===level));document.getElementById('trade-profession').innerHTML+=tradeProfessions.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');document.getElementById('trade-level').innerHTML+=tradeLevels.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');document.getElementById('trade-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(filterTrades,150)};document.getElementById('trade-profession').onchange=filterTrades;document.getElementById('trade-level').onchange=filterTrades;document.getElementById('clear-trades').onclick=()=>{document.getElementById('trade-search').value='';document.getElementById('trade-profession').value='';document.getElementById('trade-level').value='';filterTrades()};
const allPlaces=[...data.places.structures,...data.places.locations];let placePage=1,placeFiltered=allPlaces;const PLACE_PAGE_SIZE=30;
function placeItem(item){const catalog=data.items.find(candidate=>candidate.id===item.id),icon=item.icon||catalog?.icon||iconMap.get(item.id);return `<button class="place-item open-catalog-item" data-item-key="${esc(catalog?.key||'')}">${icon?`<img loading="lazy" src="${esc(icon)}" alt="">`:''}<span><b>${esc(item.name)}</b><code>${esc(item.id)}</code></span></button>`}
function structureCard(item){const placement=item.placement,placementFacts=placement?`<h3>Placement</h3><div class="place-facts">${[['Set',placement.setId],['Type',placement.type],['Spacing',placement.spacing],['Separation',placement.separation],['Salt',placement.salt]].filter(([,value])=>value!=null).map(([key,value])=>`<div><b>${esc(key)}</b>${esc(value)}</div>`).join('')}</div>`:'';const biomes=item.biomes.length?item.biomes.map(value=>`<code>${esc(value)}</code>`).join(''):item.biomeSelector?`<code>${esc(item.biomeSelector)}</code>`:'Not specified';return `<article class="place-card"><div class="place-heading"><span class="place-kind">${esc(item.kind)}</span><h2>${esc(item.name)}</h2><code>${esc(item.id)}</code></div><div class="place-facts">${[['Structure type',item.type],['Generation step',item.step],['Terrain adaptation',item.terrainAdaptation],['Start pool',item.startPool],['Jigsaw size',item.size],['Maximum distance',item.maxDistance]].filter(([,value])=>value!=null).map(([key,value])=>`<div><b>${esc(key)}</b>${esc(value)}</div>`).join('')}</div><h3>Biomes</h3><div class="biome-list">${biomes}</div>${placementFacts}<p class="provenance">${esc(item.source)}</p></article>`}
function lootPlaceCard(item){return `<article class="place-card"><div class="place-heading"><span class="place-kind">${esc(item.kind)}</span><h2>${esc(item.name)}</h2><code>${esc(item.id)}</code></div><details class="place-loot" open><summary>${item.items.length} obtainable item${item.items.length===1?'':'s'}</summary><div class="place-items">${item.items.map(placeItem).join('')}</div></details><p class="provenance">${esc(item.source)}</p></article>`}
function placeCard(item){return item.kind==='Structure definition'?structureCard(item):lootPlaceCard(item)}
function wirePlaces(root){root.querySelectorAll('.open-catalog-item').forEach(button=>button.onclick=()=>{if(button.dataset.itemKey)openCatalogItem(button.dataset.itemKey)})}
function renderPlaces(){const start=(placePage-1)*PLACE_PAGE_SIZE,pages=Math.max(1,Math.ceil(placeFiltered.length/PLACE_PAGE_SIZE)),root=document.getElementById('place-results');root.innerHTML=placeFiltered.slice(start,start+PLACE_PAGE_SIZE).map(placeCard).join('')||'<div class="empty">No places match these filters.</div>';wirePlaces(root);document.getElementById('place-stats').textContent=`Showing ${placeFiltered.length} of ${allPlaces.length} source-backed place records (${data.places.structures.length} structures, ${data.places.locations.length} loot locations)`;document.getElementById('place-pager').innerHTML=`<button id="place-prev" ${placePage===1?'disabled':''}>Previous</button><span>Page ${placePage} of ${pages}</span><button id="place-next" ${placePage===pages?'disabled':''}>Next</button>`;document.getElementById('place-prev').onclick=()=>{placePage--;renderPlaces();scrollTo(0,0)};document.getElementById('place-next').onclick=()=>{placePage++;renderPlaces();scrollTo(0,0)}}
function filterPlaces(){const q=norm(document.getElementById('place-search').value),kind=document.getElementById('place-kind').value;placeFiltered=allPlaces.filter(item=>spoilerAllowed('place',item.id)&&(!kind||item.kind===kind)&&(!q||[item.name,item.id,item.kind,item.type,item.step,item.terrainAdaptation,item.startPool,item.biomeSelector,...(item.biomes||[]),...(item.items||[]).flatMap(entry=>[entry.id,entry.name])].some(value=>norm(value).includes(q))));placePage=1;renderPlaces()}
document.getElementById('place-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(filterPlaces,150)};document.getElementById('place-kind').onchange=filterPlaces;document.getElementById('clear-places').onclick=()=>{document.getElementById('place-search').value='';document.getElementById('place-kind').value='';filterPlaces()};
function archaeologyVisual(item){return `<span class="archaeology-item">${item.icon?`<img loading="lazy" src="${esc(item.icon)}" alt="">`:''}<span><b>${esc(item.name)}</b><code>${esc(item.id)}</code></span></span>`}
function archaeologyEntry(entry){const resolved=entry.resolvedItems.length?`<details><summary>${entry.resolvedItems.length} possible nested item${entry.resolvedItems.length===1?'':'s'}</summary><div class="archaeology-resolved">${entry.resolvedItems.map(archaeologyVisual).join('')}</div></details>`:'';return `<div class="archaeology-entry"><span class="entry-kind">${esc(entry.kind)}</span>${archaeologyVisual(entry)}<div class="entry-stats"><span>Weight ${esc(entry.weight)}</span><span>Quality ${esc(entry.quality)}</span>${entry.baseChance!=null?`<span>${esc(entry.baseChance)}% base share</span>`:''}${entry.conditional?'<span>Conditional</span>':''}</div>${resolved}</div>`}
function archaeologyCard(site){return `<article class="archaeology-card"><div class="place-heading"><span class="place-kind">Archaeology loot table</span><h2>${esc(site.name)}</h2><code>${esc(site.id)}</code></div><div class="place-facts"><div><b>Table type</b>${esc(site.tableType||'Not specified')}</div><div><b>Pool rolls</b>${site.rolls.map(esc).join(', ')}</div><div><b>Direct entries</b>${site.entries.length}</div></div><div class="archaeology-entries">${site.entries.map(archaeologyEntry).join('')}</div><p class="provenance">${esc(site.source)}</p></article>`}
function wireArchaeology(root){wirePlaces(root)}
function renderArchaeology(){const q=norm(document.getElementById('archaeology-search').value),sites=data.archaeology.filter(site=>!q||[site.name,site.id,site.tableType,...site.entries.flatMap(entry=>[entry.name,entry.id,...entry.resolvedItems.flatMap(item=>[item.name,item.id])])].some(value=>norm(value).includes(q)));const root=document.getElementById('archaeology-results');root.innerHTML=sites.map(archaeologyCard).join('')||'<div class="empty">No archaeology tables match this search.</div>';wireArchaeology(root);document.getElementById('archaeology-stats').textContent=`Showing ${sites.length} of ${data.archaeology.length} archaeology loot tables`}
document.getElementById('archaeology-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(renderArchaeology,150)};document.getElementById('clear-archaeology').onclick=()=>{document.getElementById('archaeology-search').value='';renderArchaeology()};
function fishingEntry(entry){const resolved=entry.resolvedItems.length?`<details><summary>${entry.resolvedItems.length} possible item${entry.resolvedItems.length===1?'':'s'}</summary><div class="archaeology-resolved">${entry.resolvedItems.map(archaeologyVisual).join('')}</div></details>`:'';const modifiers=entry.modifiers.length?`<div class="entry-modifiers">${entry.modifiers.map(value=>`<span>${esc(value)}</span>`).join('')}</div>`:'';return `<div class="fishing-entry"><span class="entry-kind">${esc(entry.kind)}</span>${archaeologyVisual(entry)}<div class="entry-stats"><span>Weight ${esc(entry.weight)}</span><span>Quality ${esc(entry.quality)}</span>${entry.baseChance!=null?`<span>${esc(entry.baseChance)}% table share</span>`:''}</div>${entry.conditions.length?`<div class="condition-list">${entry.conditions.map(value=>`<span>${esc(value)}</span>`).join('')}</div>`:''}${modifiers}${resolved}</div>`}
function fishingEligibility(record){if(!record.active)return '<div class="condition-list"><span>Not referenced by the active fishing router</span></div>';if(record.globalBiomes)return '<div class="condition-list"><span>All biomes</span></div>';const selectors=record.biomeSelectors.length?`<div class="condition-list">${record.biomeSelectors.map(value=>`<span>${esc(value)}</span>`).join('')}</div>`:'';const biomes=record.biomes.length?`<details class="fishing-biomes"><summary>${record.biomes.length} eligible biome${record.biomes.length===1?'':'s'}</summary><div class="biome-list">${record.biomes.map(value=>`<code>${esc(value)}</code>`).join('')}</div></details>`:'';return selectors+biomes}
function fishingRecordCard(record){const eligibility=fishingEligibility(record);if(record.role==='Species'&&record.entries.length===1){const entry=record.entries[0];return `<article class="species-card"><div><span class="place-kind">${esc(record.role)}</span><h3>${esc(record.name)}</h3><code>${esc(record.id)}</code>${eligibility}</div>${fishingEntry(entry)}<p class="provenance">${esc(record.source)}</p></article>`}return `<article class="fishing-card"><div class="place-heading"><span class="place-kind">${esc(record.role)}</span><h2>${esc(record.name)}</h2><code>${esc(record.id)}</code></div>${eligibility}<div class="fishing-entries">${record.entries.map(fishingEntry).join('')}</div><p class="provenance">${esc(record.source)}</p></article>`}
function renderFishingRoutes(){document.getElementById('fishing-routes').innerHTML=data.fishing.routes.map(entry=>`<article class="route-card"><b>${esc(entry.name)}</b><code>${esc(entry.id)}</code><div class="entry-stats"><span>Weight ${esc(entry.weight)}</span><span>Quality ${esc(entry.quality)}</span></div>${entry.conditions.length?`<div class="condition-list">${entry.conditions.map(value=>`<span>${esc(value)}</span>`).join('')}</div>`:'<div class="condition-list"><span>Always eligible</span></div>'}</article>`).join('')}
let fishingPage=1,fishingFiltered=data.fishing.tables;const FISHING_PAGE_SIZE=20;
