function renderFishing(){const start=(fishingPage-1)*FISHING_PAGE_SIZE,pages=Math.max(1,Math.ceil(fishingFiltered.length/FISHING_PAGE_SIZE)),root=document.getElementById('fishing-results');root.innerHTML=fishingFiltered.slice(start,start+FISHING_PAGE_SIZE).map(fishingRecordCard).join('')||'<div class="empty">No fishing content matches these filters.</div>';wireFishing(root);document.getElementById('fishing-stats').textContent=`Showing ${fishingFiltered.length} of ${data.fishing.tables.length} fishing tables`;document.getElementById('fishing-pager').innerHTML=`<button id="fishing-prev" ${fishingPage===1?'disabled':''}>Previous</button><span>Page ${fishingPage} of ${pages}</span><button id="fishing-next" ${fishingPage===pages?'disabled':''}>Next</button>`;document.getElementById('fishing-prev').onclick=()=>{fishingPage--;renderFishing();scrollTo(0,0)};document.getElementById('fishing-next').onclick=()=>{fishingPage++;renderFishing();scrollTo(0,0)}}
