document.getElementById('fishing-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(filterFishing,150)};document.getElementById('fishing-role').onchange=filterFishing;document.getElementById('clear-fishing').onclick=()=>{document.getElementById('fishing-search').value='';document.getElementById('fishing-role').value='';filterFishing()};
let foodPage=1,foodFiltered=data.foodItems;const FOOD_PAGE_SIZE=24;
