document.getElementById('effect-filter').innerHTML+=data.foodEffects.map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');document.getElementById('food-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(filterFoods,150)};document.getElementById('effect-filter').onchange=filterFoods;document.getElementById('effect-kind').onchange=filterFoods;document.getElementById('clear-food').onclick=()=>{document.getElementById('food-search').value='';document.getElementById('effect-filter').value='';document.getElementById('effect-kind').value='';filterFoods()};
let itemPage=1,itemFiltered=data.items;const ITEM_PAGE_SIZE=48;
function catalogCard(item){return `<button class="catalog-item" data-item-key="${esc(item.key)}">${item.icon?`<img loading="lazy" src="${esc(item.icon)}" alt="">`:''}<span><b>${esc(item.name)}</b><code>${esc(item.id)}</code><small>${esc(item.category)}${item.custom?' | custom variant':''}</small></span></button>`}
