const itemCategories=[...new Set(data.items.map(item=>item.category))].sort();document.getElementById('item-category').innerHTML+=itemCategories.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');document.getElementById('item-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(filterItems,150)};document.getElementById('item-category').onchange=filterItems;document.getElementById('clear-items').onclick=()=>{document.getElementById('item-search').value='';document.getElementById('item-category').value='';filterItems()};
const enchantmentById=new Map(data.enchantments.map(item=>[item.id,item]));
function enchantmentCard(item){const facts=[['Maximum level',item.max],['Slots',item.slots.join(', ')||'Not specified'],['Weight',item.weight??'Not specified'],['Anvil cost',item.anvilCost??'Not specified'],['Triggers',item.effectTriggers.map(x=>x.replace('minecraft:','').replaceAll('_',' ')).join(', ')||'None']];const supported=item.items.length?`<h3>Compatible equipment</h3><div class="related-buttons">${item.items.map(id=>{const icon=iconMap.get(canonical(id));return `<button class="open-base-item" data-item-id="${esc(canonical(id))}">${icon?`<img loading="lazy" src="${esc(icon)}" alt="">`:''}${esc(id.replace('minecraft:','').replaceAll('_',' '))}</button>`}).join('')}</div>`:'';const equipment=item.equipment.length?`<h3>Equipment carrying this enchantment</h3><div class="related-buttons">${item.equipment.map(entry=>`<button class="open-catalog-item" data-item-key="${esc(entry.itemKey)}">${entry.icon?`<img loading="lazy" src="${esc(entry.icon)}" alt="">`:''}${esc(entry.name)} ${entry.level>1?' '+entry.level:''}</button>`).join('')}</div>`:'';const visibleBlessings=item.blessings.filter(entry=>spoilerAllowed('blessing',entry.id)),blessings=visibleBlessings.length?`<h3>Included in Blessings</h3><div class="related-buttons">${visibleBlessings.map(entry=>`<button class="open-blessing" data-blessing-id="${esc(entry.id)}">${esc(entry.name)} ${entry.level>1?' '+entry.level:''}</button>`).join('')}</div>`:'';const technical=item.functions.length?`<details class="technical"><summary>Technical function commands</summary>${item.functions.map(fn=>`<h4>${esc(fn.id)}</h4><pre>${esc(fn.commands.join('\\n'))}</pre><div class="provenance">${esc(fn.source)}</div>`).join('')}</details>`:'';return `<details class="enchant-card"><summary><strong>${esc(item.name)}</strong><span>${esc(item.summary||'Custom enchantment')}</span><code>${esc(item.id)}</code></summary><div class="enchant-body">${item.inGameName&&item.inGameName!==item.name?`<p><b>In-game display:</b> ${esc(item.inGameName)}</p>`:''}<p>${esc(item.summary||'No reviewed behavior summary is available.')}</p>${item.activation?`<p><b>Activation:</b> ${esc(item.activation)}</p>`:''}${item.scaling?`<p><b>Scaling:</b> ${esc(item.scaling)}</p>`:''}<div class="enchant-facts">${facts.map(([key,value])=>`<div class="enchant-fact"><b>${esc(key)}</b>${esc(value)}</div>`).join('')}</div>${supported}${equipment}${blessings}${technical}<p class="provenance">${esc(item.provenance)} | ${esc(item.source)}</p></div></details>`}
