function renderEnchantments(){const q=norm(document.getElementById('enchantment-search').value),items=data.enchantments.filter(item=>!q||[item.name,item.inGameName,item.id,item.summary,item.activation,item.scaling,...item.effectTriggers,...item.items].some(value=>norm(value).includes(q)));const root=document.getElementById('enchantment-results');root.innerHTML=items.map(enchantmentCard).join('')||'<div class="empty">No enchantments match this search.</div>';wireEnchantments(root);document.getElementById('enchantment-stats').textContent=`Showing ${items.length} of ${data.enchantments.length} custom enchantments`}
document.getElementById('enchantment-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(renderEnchantments,150)};document.getElementById('clear-enchantments').onclick=()=>{document.getElementById('enchantment-search').value='';renderEnchantments()};
function blessingCard(item){const recipe=data.recipes.find(entry=>entry.id===item.recipeId);return `<details class="blessing-card"><summary><strong>${esc(item.name)}</strong><span>${item.enchantments.length} enchantments</span><code>${esc(item.id)}</code></summary><div class="blessing-body"><div class="blessing-enchants">${item.enchantments.map(enchantment=>enchantmentById.has(enchantment.id)?`<button class="open-enchantment" data-enchantment-id="${esc(enchantment.id)}">${esc(enchantment.name)} ${enchantment.level}</button>`:`<span>${esc(enchantment.name)} ${enchantment.level}</span>`).join('')}</div>${recipe?`<h3>Crafting recipe</h3>${card(recipe)}`:''}<p class="provenance">${esc(item.source)}</p></div></details>`}
function wireBlessings(root){root.querySelectorAll('.open-enchantment').forEach(button=>button.onclick=()=>{showPage('enchantments');document.getElementById('enchantment-search').value=button.dataset.enchantmentId;renderEnchantments()});wire(root)}
function renderBlessings(){const q=norm(document.getElementById('blessing-search').value),items=data.blessings.filter(item=>spoilerAllowed('blessing',item.id)&&(!q||norm(item.name).includes(q)||norm(item.id).includes(q)||item.enchantments.some(enchantment=>norm(enchantment.name).includes(q)||norm(enchantment.id).includes(q))));const root=document.getElementById('blessing-results');root.innerHTML=items.map(blessingCard).join('')||(spoilerMode!=='complete'?spoilerGate('blessing',data.blessings[0]?.id):'<div class="empty">No Blessings match this search.</div>');wireBlessings(root);document.getElementById('blessing-stats').textContent=`Showing ${items.length} of ${data.blessings.length} Blessings`}
