const advancementById=new Map(data.advancements.map(item=>[item.id,item]));
function advancementCard(item){const icon=item.icon||data.items.find(candidate=>candidate.id===item.iconId&&candidate.icon)?.icon;return `<article class="advancement-card frame-${esc(item.frame)} ${item.hidden?'hidden-advancement':''}">${icon?`<img class="advancement-icon" loading="lazy" src="${esc(icon)}" alt="">`:'<span></span>'}<div><b>${esc(item.title)}</b><p>${esc(item.description||'No description supplied by the pack.')}</p><small>${esc(item.section)}${item.hidden?' | hidden advancement':''}</small></div><code>${esc(item.id)}</code></article>`}
function renderAdvancements(){const q=norm(document.getElementById('advancement-search').value),section=document.getElementById('advancement-section').value,items=data.advancements.filter(item=>spoilerAllowed('advancement',item.id)&&(!section||item.section===section)&&(!q||[item.title,item.description,item.id,item.parent].some(value=>norm(value).includes(q))));document.getElementById('advancement-results').innerHTML=items.map(advancementCard).join('')||'<div class="empty">No visible advancements match these filters.</div>';document.getElementById('advancement-stats').textContent=`Showing ${items.length} of ${data.advancements.length} advancement entries`}
function openAdvancement(id){const item=advancementById.get(id);if(!item)return;showPage('progression');document.getElementById('advancement-search').value=id;renderAdvancements();document.getElementById('advancement-results').scrollIntoView({behavior:'smooth'})}
function renderProgressionPath(){const root=document.getElementById('progression-path');root.className='progression-path';root.innerHTML=data.progression.map((stage,index)=>{const stageNumber=index+1;if(spoilerMode!=='complete'&&stageNumber>spoilerLimit())return `<article class="progression-stage"><h2>Stage ${stageNumber}</h2>${spoilerGate('advancement',stage.advancements[0])}</article>`;const milestones=stage.advancements.map(id=>{const item=advancementById.get(id);return item&&spoilerAllowed('advancement',id)?`<button data-advancement-id="${esc(id)}">${esc(item.title)}</button>`:''}).join('');return `<article class="progression-stage"><h2>${esc(stage.title)}</h2><p>${esc(stage.summary)}</p><div class="milestone-links">${milestones}</div></article>`}).join('');root.querySelectorAll('[data-advancement-id]').forEach(button=>button.onclick=()=>openAdvancement(button.dataset.advancementId))}
const advancementSections=[...new Set(data.advancements.map(item=>item.section))].sort();document.getElementById('advancement-section').innerHTML+=advancementSections.map(value=>`<option value="${esc(value)}">${esc(value.replaceAll('_',' '))}</option>`).join('');document.getElementById('advancement-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(renderAdvancements,150)};document.getElementById('advancement-section').onchange=renderAdvancements;document.getElementById('clear-advancements').onclick=()=>{document.getElementById('advancement-search').value='';document.getElementById('advancement-section').value='';renderAdvancements()};
const releaseHistory=data.releaseHistory;
function releaseCard(item){const date=item.published?new Date(item.published).toLocaleDateString():'',details=spoilerMode==='complete'?(item.changelog?`<pre>${esc(item.changelog)}</pre>`:'<div class="empty">No changelog was published for this release.</div>'):spoilerGate('release',item.id);return `<details class="release-card" ${item.current?'open':''}><summary><span><strong>${esc(item.version)}</strong> ${item.current?'<span class="current-release">current ZIP</span>':''}</span><span>${spoilerMode==='complete'?esc(item.name):'Release details hidden'}</span><span class="release-type ${esc(item.type)}">${esc(item.type)}</span><time>${esc(date)}</time></summary><div class="release-body"><div class="release-games">Minecraft ${item.gameVersions.map(esc).join(', ')}</div>${details}</div></details>`}
function comparisonGroup(group){const sections=['added','removed','changed'].map(state=>group[state].length?`<details><summary>${state[0].toUpperCase()+state.slice(1)} (${group[state].length})</summary><ul>${group[state].map(item=>`<li><code>${esc(item.id)}</code><small>${esc(item.path)}</small></li>`).join('')}</ul></details>`:'').join('');return `<article class="comparison-group"><h3>${esc(group.name)}</h3>${sections}</article>`}
function renderReleases(){if(!releaseHistory){document.getElementById('release-summary').innerHTML='<div class="empty">This build does not include Modrinth metadata. Rebuild with --modrinth-project to add it.</div>';document.getElementById('version-comparison').innerHTML='';document.getElementById('release-results').innerHTML='';document.getElementById('release-stats').textContent='';return}const q=norm(document.getElementById('release-search').value),type=document.getElementById('release-type').value,releases=releaseHistory.releases.filter(item=>(!type||item.type===type)&&(!q||(spoilerMode==='complete'?[item.version,item.name,item.type,item.changelog,...item.gameVersions]:[item.version,item.type,...item.gameVersions]).some(value=>norm(value).includes(q))));document.getElementById('release-summary').innerHTML=`<div class="release-summary"><div><b>Official source</b><a href="${esc(releaseHistory.project.url)}" target="_blank" rel="noopener">${esc(releaseHistory.project.title)}</a></div><div><b>Current ZIP</b>${esc(releaseHistory.currentVersion||'Not matched')}</div><div><b>Latest stable</b>${esc(releaseHistory.latestStable||'Unknown')}</div><div><b>Latest published</b>${esc(releaseHistory.latestPublished||'Unknown')}</div></div>`;const comparison=releaseHistory.comparison;if(comparison&&spoilerMode==='complete'){const summary=comparison.summary;document.getElementById('version-comparison').innerHTML=`<h2>ZIP comparison: ${esc(comparison.baselineVersion)} to ${esc(comparison.currentVersion)}</h2><div class="comparison-summary"><span>${summary.added} added</span><span>${summary.removed} removed</span><span>${summary.changed} changed</span><span>${summary.unchanged} unchanged</span></div><div class="comparison-grid">${comparison.categories.map(comparisonGroup).join('')}</div>`}else if(comparison)document.getElementById('version-comparison').innerHTML=spoilerGate('release','comparison');else document.getElementById('version-comparison').innerHTML='<div class="empty">No earlier stable release was available for comparison.</div>';document.getElementById('release-results').innerHTML=releases.map(releaseCard).join('')||'<div class="empty">No releases match these filters.</div>';document.getElementById('release-stats').textContent=`Showing ${releases.length} of ${releaseHistory.releases.length} published versions`}
document.getElementById('release-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(renderReleases,150)};document.getElementById('release-type').onchange=renderReleases;document.getElementById('clear-releases').onclick=()=>{document.getElementById('release-search').value='';document.getElementById('release-type').value='';renderReleases()};
function differenceCard(item){return `<article class="difference-card"><span class="category">${esc(item.category)}</span> <span class="provenance-badge">${esc(item.provenance)}</span><h2>${esc(item.title)}</h2><p>${esc(item.summary)}</p><div class="source-citations">${item.sources.map(source=>`<code>${esc(source)}</code>`).join('')}</div></article>`}
function renderDifferences(){const q=norm(document.getElementById('difference-search').value),category=document.getElementById('difference-category').value,items=data.differences.filter(item=>spoilerAllowed('difference',item.title)&&(!category||item.category===category)&&(!q||[item.category,item.title,item.summary,...item.sources].some(value=>norm(value).includes(q))));document.getElementById('difference-results').className='difference-grid';document.getElementById('difference-results').innerHTML=items.map(differenceCard).join('')||'<div class="empty">No visible changes match these filters.</div>';document.getElementById('difference-stats').textContent=`Showing ${items.length} of ${data.differences.length} documented changes`}
const differenceCategories=[...new Set(data.differences.map(item=>item.category))].sort();document.getElementById('difference-category').innerHTML+=differenceCategories.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');document.getElementById('difference-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(renderDifferences,150)};document.getElementById('difference-category').onchange=renderDifferences;document.getElementById('clear-differences').onclick=()=>{document.getElementById('difference-search').value='';document.getElementById('difference-category').value='';renderDifferences()};
function globalGroup(title,total,content){return total?`<section class="search-group"><h2>${title}<span class="count">${total} found${total>12?' | first 12 shown':''}</span></h2>${content}</section>`:''}
function runGlobalSearch(){
 const q=norm(document.getElementById('global-search').value),root=document.getElementById('global-results');if(!q){root.innerHTML='<div class="empty global-empty">Enter a search term.</div>';document.getElementById('global-stats').textContent='';return}
 activeQuery=q;
 const items=data.items.filter(item=>spoilerAllowed('item',item.key)&&[item.name,item.id,...item.lore,...item.properties].some(value=>norm(value).includes(q)));
 const recipes=data.recipes.filter(recipe=>spoilerAllowed('recipe',recipe.id)&&norm(recipe.search).includes(q));
 const foods=data.foodItems.filter(item=>norm(item.name).includes(q)||norm(item.underlyingId).includes(q)||item.effects.some(effect=>norm(effect.name).includes(q)||norm(effect.id).includes(q))||item.removes.some(effect=>norm(effect.name).includes(q)));
 const enchantments=data.enchantments.filter(item=>[item.name,item.inGameName,item.id,item.summary,item.activation,item.scaling,...item.effectTriggers,...item.items,...item.functions.flatMap(fn=>fn.commands)].some(value=>norm(value).includes(q)));
 const blessings=data.blessings.filter(item=>spoilerAllowed('blessing',item.id)&&(norm(item.name).includes(q)||norm(item.id).includes(q)||item.enchantments.some(enchantment=>norm(enchantment.name).includes(q)||norm(enchantment.id).includes(q))));
 const sourceRecords=data.acquisition.filter(item=>item.sources.some(source=>!['Chest loot','Archaeology'].includes(source.kind)&&(norm(source.kind).includes(q)||norm(source.location).includes(q)||norm(source.id).includes(q))));
 const sourceItems=[...new Map(sourceRecords.map(record=>{const item=catalogByKey.get(`base:${record.id}`);return item?[item.key,item]:[record.id,null]}).filter(([,item])=>item&&spoilerAllowed('item',item.key))).values()];
 const mechanics=data.mechanics.filter(name=>norm(name).includes(q));
 const advancements=data.advancements.filter(item=>spoilerAllowed('advancement',item.id)&&[item.title,item.description,item.id,item.section].some(value=>norm(value).includes(q)));
 const differences=data.differences.filter(item=>spoilerAllowed('difference',item.title)&&[item.category,item.title,item.summary,...item.sources].some(value=>norm(value).includes(q)));
 const trades=data.trades.filter(trade=>spoilerAllowed('trade',trade.id)&&[trade.id,trade.profession,trade.level,trade.result.id,trade.result.name,...trade.costs.flatMap(item=>[item.id,item.name]),...trade.bundleContents.flatMap(item=>[item.id,item.name])].some(value=>norm(value).includes(q)));
 const places=allPlaces.filter(item=>spoilerAllowed('place',item.id)&&item.kind!=='Archaeology'&&[item.name,item.id,item.kind,item.type,item.step,item.terrainAdaptation,item.startPool,item.biomeSelector,...(item.biomes||[]),...(item.items||[]).flatMap(entry=>[entry.id,entry.name])].some(value=>norm(value).includes(q)));
 const archaeology=data.archaeology.filter(site=>[site.name,site.id,site.tableType,...site.entries.flatMap(entry=>[entry.name,entry.id,...entry.resolvedItems.flatMap(item=>[item.name,item.id])])].some(value=>norm(value).includes(q)));
 const fishing=data.fishing.tables.filter(record=>[record.name,record.id,record.role,...record.biomeSelectors,...record.biomes,...record.entries.flatMap(entry=>[entry.name,entry.id,...entry.conditions,...entry.modifiers,...entry.resolvedItems.flatMap(item=>[item.name,item.id])])].some(value=>norm(value).includes(q)));
 const releases=releaseHistory?releaseHistory.releases.filter(item=>(spoilerMode==='complete'?[item.version,item.name,item.type,item.changelog,...item.gameVersions]:[item.version,item.type,...item.gameVersions]).some(value=>norm(value).includes(q))):[];
 const total=items.length+recipes.length+foods.length+enchantments.length+blessings.length+sourceItems.length+mechanics.length+advancements.length+differences.length+trades.length+places.length+archaeology.length+fishing.length+releases.length;
 root.innerHTML=globalGroup('Items',items.length,`<div class="item-grid">${items.slice(0,12).map(catalogCard).join('')}</div>`)+globalGroup('Recipes',recipes.length,recipes.slice(0,12).map(card).join(''))+globalGroup('Food and effects',foods.length,foods.slice(0,12).map(foodCard).join(''))+globalGroup('Villager trades',trades.length,trades.slice(0,12).map(tradeCard).join(''))+globalGroup('Places and structures',places.length,places.slice(0,12).map(placeCard).join(''))+globalGroup('Archaeology',archaeology.length,archaeology.slice(0,12).map(archaeologyCard).join(''))+globalGroup('Fishing',fishing.length,fishing.slice(0,12).map(fishingRecordCard).join(''))+globalGroup('Releases',releases.length,releases.slice(0,12).map(releaseCard).join(''))+globalGroup('Enchantments',enchantments.length,enchantments.slice(0,12).map(enchantmentCard).join(''))+globalGroup('Blessings',blessings.length,blessings.slice(0,12).map(blessingCard).join(''))+globalGroup('Progression advancements',advancements.length,advancements.slice(0,12).map(advancementCard).join(''))+globalGroup('Differences from Vanilla',differences.length,`<div class="difference-grid">${differences.slice(0,12).map(differenceCard).join('')}</div>`)+globalGroup('Other acquisition sources',sourceItems.length,`<div class="item-grid">${sourceItems.slice(0,12).map(catalogCard).join('')}</div>`)+globalGroup('Mechanics',mechanics.length,`<div class="search-group-grid">${mechanics.map(name=>`<div class="search-hit"><b>${esc(name)}</b><small>Gameplay mechanic</small></div>`).join('')}</div>`)||'<div class="empty">No results found.</div>';
 document.getElementById('global-stats').textContent=`${total} results across the wiki`;
 wireCatalog(root);wire(root);wireFoodLinks(root);wireEnchantments(root);wireBlessings(root);wirePlaces(root);wireArchaeology(root);wireFishing(root)
}
document.getElementById('global-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(runGlobalSearch,150)};document.getElementById('clear-global').onclick=()=>{document.getElementById('global-search').value='';runGlobalSearch()};
function refreshSpoilers(){renderSpoilerDatalists();search();filterItems();filterTrades();filterPlaces();renderEnchantments();renderBlessings();renderOptimumBuilds();renderAdvancements();renderProgressionPath();renderReleases();renderDifferences();if(document.getElementById('reverse-search').value.trim())reverse();if(document.getElementById('obtain-search').value.trim())obtain();if(document.getElementById('global-search').value)runGlobalSearch()}
const categories=[...new Set(data.recipes.map(r=>r.namespace))].sort();document.getElementById('category').innerHTML+=[...categories].map(x=>`<option value="${esc(x)}">${esc(x.replaceAll('_',' '))}</option>`).join('');
document.getElementById('ibox-recipes').textContent=data.recipes.length.toLocaleString();document.getElementById('ibox-foods').textContent=data.foodItems.length;document.getElementById('ibox-trades').textContent=data.trades.length;document.getElementById('ibox-enchants').textContent=data.enchantments.length;const counts={};data.recipes.forEach(r=>counts[r.namespace]=(counts[r.namespace]||0)+1);document.getElementById('summary').innerHTML='<table class="wikitable"><tr><th>Recipe group</th><th>Count</th></tr>'+Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${esc(k.replaceAll('_',' '))}</td><td>${v}</td></tr>`).join('')+'</table>';
document.getElementById('mechanic-list').innerHTML='<ul>'+data.mechanics.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>';document.getElementById('override-table').innerHTML='<table class="wikitable"><tr><th>Data type</th><th>Files</th></tr>'+data.overrides.sort((a,b)=>b.count-a.count).map(x=>`<tr><td><code>${esc(x.type)}</code></td><td>${x.count}</td></tr>`).join('')+'</table>';
renderSpoilerDatalists();search();filterTrades();filterPlaces();renderArchaeology();renderFishingRoutes();renderFishing();renderFoods();filterItems();renderEnchantments();renderBlessings();renderOptimumBuilds();renderAdvancements();renderProgressionPath();renderReleases();renderDifferences();showPage(location.hash.slice(1)||'overview',false);
